def find_magic_sequence(n, fixed=None):
    if fixed is None:
        fixed = {}

    solutions = []

    def search(idx, current, remaining_sum, remaining_weighted_sum):
        if idx == n:
            if remaining_sum == 0 and remaining_weighted_sum == 0:
                counts = [0]*n
                for v in current:
                    if 0 <= v < n:
                        counts[v] += 1
                if counts == current:
                    solutions.append(current[:])
            return

        if idx in fixed:
            val = fixed[idx]
            if val < 0 or val > remaining_sum:
                return
            new_rem_sum = remaining_sum - val
            new_rem_weighted = remaining_weighted_sum - idx * val
            if new_rem_weighted < 0:
                return
            current.append(val)
            search(idx+1, current, new_rem_sum, new_rem_weighted)
            current.pop()
        else:
            max_val = min(remaining_sum, n)
            if idx > 0:
                max_val = min(max_val, remaining_weighted_sum // idx)
            for val in range(max_val, -1, -1):
                new_rem_sum = remaining_sum - val
                new_rem_weighted = remaining_weighted_sum - idx * val
                if new_rem_weighted < 0:
                    continue
                if new_rem_sum > (n - idx - 1) * n:
                    continue
                current.append(val)
                search(idx+1, current, new_rem_sum, new_rem_weighted)
                current.pop()

    search(0, [], n, n)
    return solutions

sols9 = find_magic_sequence(9, fixed={4:0})
print("n=9 solutions with x[4]=0:", sols9)
